-- Counters live on the rows (course Chapter 1), so set them from the real rows.
UPDATE communities c SET member_count = (SELECT COUNT(*) FROM community_members m WHERE m.community_id = c.id);
UPDATE posts p SET
    like_count    = (SELECT COUNT(*) FROM post_likes l WHERE l.post_id = p.id),
    comment_count = (SELECT COUNT(*) FROM comments x WHERE x.post_id = p.id AND x.status = 'ACTIVE')
WHERE p.id::text LIKE 'de3a0000-%';
COMMIT;
